INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7568532, 1214801, 83313, '<td valign="top">A unique take on the topic, though it took me a moment to realize they were waiting for a drawbridge to open. My first thought was the bridge of a ship.</td>', 'A unique take on the topic, though it took me a moment to realize they were waiting for a drawbridge to open. My first thought was the bridge of a ship.', '2018-05-16 01:16:22.000000', NULL, 1),
(7568560, 1214517, 34337, '<td valign="top">Good colors.  Horizon is tilted; sometimes OK, but doesn''t work as well in this instance.  Great timing on the shot: subjects are in perfect pose.  In future, use tripod with level to fix horizon issues, or else use on-screen grid in camera software to level.  Good luck!</td>', 'Good colors.  Horizon is tilted; sometimes OK, but doesn''t work as well in this instance.  Great timing on the shot: subjects are in perfect pose.  In future, use tripod with level to fix horizon issues, or else use on-screen grid in camera software to level.  Good luck!', '2018-05-16 09:25:27.000000', NULL, 1),
(7568561, 1214757, 34337, '<td valign="top">Interesting saturation.  I would love to see this in B&amp;W, especially with the old-style signage.  Good shot.</td>', 'Interesting saturation.  I would love to see this in B&W, especially with the old-style signage.  Good shot.', '2018-05-16 09:29:04.000000', NULL, 1),
(7568562, 1214797, 34337, '<td valign="top">What a great scene/location.  Decent shot.  Something seems off about focus, might be too much post-processing (contrast, sharpening, compression, etc.).  It looks like there is a rain drop or other substance on the lens; just left of where the bridge vines cross, right on the bridge.  Otherwise, good stuff.</td>', 'What a great scene/location.  Decent shot.  Something seems off about focus, might be too much post-processing (contrast, sharpening, compression, etc.).  It looks like there is a rain drop or other substance on the lens; just left of where the bridge vines cross, right on the bridge.  Otherwise, good stuff.', '2018-05-16 09:32:39.000000', NULL, 1),
(7568563, 1214788, 34337, '<td valign="top">Good location/scene.  Nice bridge reflection.  Photo needs more depth; might be related to your camera (quality, specs).</td>', 'Good location/scene.  Nice bridge reflection.  Photo needs more depth; might be related to your camera (quality, specs).', '2018-05-16 09:35:39.000000', NULL, 1),
(7568564, 1214732, 34337, '<td valign="top">Looks like too much post processing.  On your next shot, try a less-is-more approach.  Keep shooting!</td>', 'Looks like too much post processing.  On your next shot, try a less-is-more approach.  Keep shooting!', '2018-05-16 09:36:39.000000', NULL, 1),
(7568566, 1214655, 34337, '<td valign="top">Great angle.  I really like this in portrait including the vehicles below.  Good choice.</td>', 'Great angle.  I really like this in portrait including the vehicles below.  Good choice.', '2018-05-16 09:37:56.000000', NULL, 1),
(7568567, 1214769, 34337, '<td valign="top">Nice focus on subjects and including a few foreground elements for depth.  Would like to see more of this scene; feels a bit cramped; possibly due to portrait style or lack of wide angle.</td>', 'Nice focus on subjects and including a few foreground elements for depth.  Would like to see more of this scene; feels a bit cramped; possibly due to portrait style or lack of wide angle.', '2018-05-16 09:42:19.000000', NULL, 1),
(7568568, 1214793, 34337, '<td valign="top">Good idea, but needs more practice.  Try a less-is-more approach.  Focus on subject using a macro setting in camera or a macro lens and try photographing the bass guitar''s bridge from a few different angles.</td>', 'Good idea, but needs more practice.  Try a less-is-more approach.  Focus on subject using a macro setting in camera or a macro lens and try photographing the bass guitar''s bridge from a few different angles.', '2018-05-16 09:44:30.000000', NULL, 1),
(7568569, 1214479, 34337, '<td valign="top">Good peaceful scene.  Practice a bit more on focus.  If unable to see good focus during shoot due to camera or other hurdles, then take 25 - 50 different shots with different settings and angles and check them afterwards.  Keep shooting until you get the best you can with your camera.</td>', 'Good peaceful scene.  Practice a bit more on focus.  If unable to see good focus during shoot due to camera or other hurdles, then take 25 - 50 different shots with different settings and angles and check them afterwards.  Keep shooting until you get the best you can with your camera.', '2018-05-16 09:47:57.000000', NULL, 1),
(7568572, 1214801, 34337, '<td valign="top">Creative take on "bridges".  Good focus, good colors.</td>', 'Creative take on "bridges".  Good focus, good colors.', '2018-05-16 10:01:15.000000', NULL, 1),
(7568573, 1214708, 34337, '<td valign="top">Good contrast, good b&amp;w.  Looks like maybe a bit of over-sharpening in post.</td>', 'Good contrast, good b&w.  Looks like maybe a bit of over-sharpening in post.', '2018-05-16 10:02:37.000000', NULL, 1),
(7568574, 1214786, 34337, '<td valign="top">Excellent focus and clarity.  Needs more bridge, even if ugly.</td>', 'Excellent focus and clarity.  Needs more bridge, even if ugly.', '2018-05-16 10:04:00.000000', NULL, 1),
(7568575, 1214673, 34337, '<td valign="top">You snagged some great pastels out of this scene.  Perfect horizon, lighting, and overall composition.</td>', 'You snagged some great pastels out of this scene.  Perfect horizon, lighting, and overall composition.', '2018-05-16 10:05:39.000000', NULL, 1),
(7568582, 1214657, 88291, '<td valign="top">Excellent!</td>', 'Excellent!', '2018-05-16 13:03:45.000000', NULL, 1),
(7568583, 1214793, 88291, '<td valign="top">Is that a bridge? Almost appears to be benches. Hard to tell.</td>', 'Is that a bridge? Almost appears to be benches. Hard to tell.', '2018-05-16 13:04:56.000000', NULL, 1),
(7568586, 1214792, 101668, '<td valign="top">Great image nicely seen and shot, the colour is rather unnatural. 6</td>', 'Great image nicely seen and shot, the colour is rather unnatural. 6', '2018-05-16 17:33:23.000000', NULL, 1),
(7568587, 1214673, 101668, '<td valign="top">Stunning shot. Clear winner You handled highlights and light generally, very well.</td>', 'Stunning shot. Clear winner You handled highlights and light generally, very well.', '2018-05-16 17:38:07.000000', NULL, 1),
(7568588, 1214789, 101668, '<td valign="top">Beautiful composition and not overly processed. Lovely image</td>', 'Beautiful composition and not overly processed. Lovely image', '2018-05-16 17:39:30.000000', NULL, 1),
(7568589, 1214757, 101668, '<td valign="top">Just a simple and beautiful image. Love the editing</td>', 'Just a simple and beautiful image. Love the editing', '2018-05-16 17:41:29.000000', NULL, 1),
(7568590, 1214795, 101668, '<td valign="top">I really like the simplicity of this 7</td>', 'I really like the simplicity of this 7', '2018-05-16 17:42:51.000000', NULL, 1),
(7568718, 1214708, 159132, '<td valign="top">The texture is a tad over the top or I would have gone higher. 6</td>', 'The texture is a tad over the top or I would have gone higher. 6', '2018-05-18 21:00:48.000000', NULL, 1),
(7568719, 1214538, 159132, '<td valign="top">I know it is a bridge, but I can''t quite make it out - which I love. Also like the the smidgen of light coming under/through</td>', 'I know it is a bridge, but I can''t quite make it out - which I love. Also like the the smidgen of light coming under/through', '2018-05-18 21:02:03.000000', NULL, 1),
(7568720, 1214776, 159132, '<td valign="top">It doesn''t ring out "bridge" to me</td>', 'It doesn''t ring out "bridge" to me', '2018-05-18 21:04:37.000000', NULL, 1),
(7568957, 1214721, 65234, '<td valign="top">GAH! I''m sure the view is amazing but, no. Just, no. Quite a striking image, though. Certainly got my attention.</td>', 'GAH! I''m sure the view is amazing but, no. Just, no. Quite a striking image, though. Certainly got my attention.', '2018-05-21 16:28:23.000000', NULL, 1),
(7568958, 1214792, 65234, '<td valign="top">What is with all the scary bridges? I''m going to have to go have a lie down after voting. Your scary bridge has lovely cyan tones. Would work nicely as a duotone.</td>', 'What is with all the scary bridges? I''m going to have to go have a lie down after voting. Your scary bridge has lovely cyan tones. Would work nicely as a duotone.', '2018-05-21 16:31:45.000000', NULL, 1),
(7568959, 1214795, 65234, '<td valign="top">Great shadow preceding her.</td>', 'Great shadow preceding her.', '2018-05-21 16:32:10.000000', NULL, 1),
(7568960, 1214688, 65234, '<td valign="top">That looks unnecessarily complicated for a bridge. Someone went a little nuts here.</td>', 'That looks unnecessarily complicated for a bridge. Someone went a little nuts here.', '2018-05-21 16:33:17.000000', NULL, 1),
(7568961, 1214797, 65234, '<td valign="top">Very,very pretty. I can almost hear rushing water. But this is another scary bridge. There are a surprising number of them in this challenge.</td>', 'Very,very pretty. I can almost hear rushing water. But this is another scary bridge. There are a surprising number of them in this challenge.', '2018-05-21 16:35:31.000000', NULL, 1),
(7568962, 1214685, 65234, '<td valign="top">Scary bridge; no handrails. Cool image.</td>', 'Scary bridge; no handrails. Cool image.', '2018-05-21 16:36:32.000000', NULL, 1),
(7568963, 1214517, 65234, '<td valign="top">Pretty scene. The image feels very slightly tilted to me (I think I want that horizontal part of the bridge to be straight, and the house vertically straight).</td>', 'Pretty scene. The image feels very slightly tilted to me (I think I want that horizontal part of the bridge to be straight, and the house vertically straight).', '2018-05-21 16:39:04.000000', NULL, 1),
(7568964, 1214781, 65234, '<td valign="top">Very decorative design. This *might* qualify as another scary bridge. Not sure I''d be comfortable standing at the top of that slope.</td>', 'Very decorative design. This *might* qualify as another scary bridge. Not sure I''d be comfortable standing at the top of that slope.', '2018-05-21 16:40:18.000000', NULL, 1),
(7568965, 1214786, 65234, '<td valign="top">It''s not so bad with a pretty black swan swimming in its reflection. I might have cropped out that beam on the left ... but then it is part of the bridge, and this is a bridge challenge, so maybe including it is the wiser choice.</td>', 'It''s not so bad with a pretty black swan swimming in its reflection. I might have cropped out that beam on the left ... but then it is part of the bridge, and this is a bridge challenge, so maybe including it is the wiser choice.', '2018-05-21 16:42:00.000000', NULL, 1),
(7568966, 1214720, 65234, '<td valign="top">This definitely qualifies as a scary bridge. I walked over a railroad bridge once, where you could see a-l-l the way down to the ground in between the ties. Yikes! Pretty, but scary.</td>', 'This definitely qualifies as a scary bridge. I walked over a railroad bridge once, where you could see a-l-l the way down to the ground in between the ties. Yikes! Pretty, but scary.', '2018-05-21 16:43:06.000000', NULL, 1),
(7568967, 1214507, 65234, '<td valign="top">Way too much daylight showing through. Scary bridge!</td>', 'Way too much daylight showing through. Scary bridge!', '2018-05-21 16:43:39.000000', NULL, 1),
(7568968, 1214618, 65234, '<td valign="top">How cool is that?! An actual castle bridge. Great subject, nicely captured.</td>', 'How cool is that?! An actual castle bridge. Great subject, nicely captured.', '2018-05-21 16:44:44.000000', NULL, 1),
(7569007, 1214517, 114285, '<td valign="top">So very painterly</td>', 'So very painterly', '2018-05-22 01:58:37.000000', NULL, 1),
